query:
query CurrentChangedThemeBodies($filenames: [String!]!, $mainAfter: String, $candidateAfter: String) {
 main: theme(id: "gid://shopify/OnlineStoreTheme/133290917985") { id role updatedAt files(first: 50, after: $mainAfter, filenames: $filenames) { nodes { filename checksumMd5 size body { ... on OnlineStoreThemeFileBodyText { content } } } pageInfo { hasNextPage endCursor } } }
 candidate: theme(id: "gid://shopify/OnlineStoreTheme/137888792673") { id role updatedAt files(first: 50, after: $candidateAfter, filenames: $filenames) { nodes { filename checksumMd5 size body { ... on OnlineStoreThemeFileBodyText { content } } } pageInfo { hasNextPage endCursor } } }
}

body.content:
{{ 'section-collection-list.css' | asset_url | stylesheet_tag }}
{{ 'component-card.css' | asset_url | stylesheet_tag }}
{{ 'component-slider.css' | asset_url | stylesheet_tag }}

{%- style -%}
  .section-{{ section.id }}-padding {
    padding-top: {{ section.settings.padding_top | times: 0.75 | round: 0 }}px;
    padding-bottom: {{ section.settings.padding_bottom | times: 0.75 | round: 0 }}px;
  }

  @media screen and (min-width: 750px) {
    .section-{{ section.id }}-padding {
      padding-top: {{ section.settings.padding_top }}px;
      padding-bottom: {{ section.settings.padding_bottom }}px;
    }
  }
{%- endstyle -%}

{%- liquid
  assign columns_mobile_int = section.settings.columns_mobile | plus: 0
  assign visible_block_count = 0
  for block in section.blocks
    if block.settings.collection != blank and block.settings.collection.all_products_count > 0
      assign visible_block_count = visible_block_count | plus: 1
    endif
  endfor
  assign show_mobile_slider = false
  assign section_anchor_id = section.settings.anchor_id | strip | handleize
  if section.settings.swipe_on_mobile and visible_block_count > columns_mobile_int
    assign show_mobile_slider = true
  endif

  assign localized_section_title = section.settings.title | strip
  case localized_section_title
    when 'Mommy & Me', 'Mommy and Me'
      assign localized_section_title = 'sections.breadcrumbs.cat_mommy_me' | t
    when 'Family Matching'
      assign localized_section_title = 'sections.breadcrumbs.cat_family_matching' | t
    when 'Daddy & Me - Maternity - Couples', 'Daddy and Me - Maternity - Couples'
      capture localized_section_title
        echo 'sections.breadcrumbs.cat_daddy_me' | t
        echo ' - '
        echo 'sections.breadcrumbs.cat_maternity' | t
        echo ' - '
        echo 'sections.breadcrumbs.cat_couples' | t
      endcapture
  endcase
-%}

{%- if visible_block_count > 0 -%}
<div class="color-{{ section.settings.color_scheme }} gradient"{% if section_anchor_id != blank %} id="{{ section_anchor_id }}"{% endif %}>
  <div class="collection-list-wrapper page-width isolate{% if show_mobile_slider %} page-width-desktop{% endif %}{% if section.settings.title == blank %} no-heading{% endif %}{% if section.settings.show_view_all == false or visible_block_count > collections.size %} no-mobile-link{% endif %} section-{{ section.id }}-padding">
    {%- unless section.settings.title == blank -%}
      <div class="title-wrapper-with-link{% if show_mobile_slider %} title-wrapper--self-padded-tablet-down{% else %} title-wrapper--self-padded-mobile{% endif %} title-wrapper--no-top-margin">
        <h2
          id="SectionHeading-{{ section.id }}"
          class="collection-list-title inline-richtext {{ section.settings.heading_size }}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
        >
          {{ localized_section_title }}
        </h2>

        {%- if section.settings.show_view_all and show_mobile_slider -%}
          <a
            href="{{ routes.collections_url }}"
            id="ViewAll-{{ section.id }}"
            class="link underlined-link large-up-hide{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
            aria-labelledby="ViewAll-{{ section.id }} SectionHeading-{{ section.id }}"
          >
            {{- 'sections.collection_list.view_all' | t -}}
          </a>
        {%- endif -%}
      </div>
    {%- endunless -%}

    <slider-component class="slider-mobile-gutter{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
      <ul
        class="collection-list contains-card contains-card--collection{% if settings.card_style == 'standard' %} contains-card--standard{% endif %} grid grid--{{ section.settings.columns_desktop }}-col-desktop grid--{{ section.settings.columns_mobile }}-col-tablet-down{% if section.settings.swipe_on_mobile %} slider slider--tablet grid--peek{% endif %} collection-list--{{ visible_block_count }}-items"
        id="Slider-{{ section.id }}"
        role="list"
      >
        {%- liquid
          assign columns = visible_block_count
          if columns > 3
            assign columns = 3
          endif
          assign animation_order = 0
        -%}
        {%- for block in section.blocks -%}
          {%- if block.settings.collection == blank or block.settings.collection.all_products_count == 0 -%}
            {%- continue -%}
          {%- endif -%}
          {%- assign animation_order = animation_order | plus: 1 -%}
          {%- liquid
            assign collection_list_item_has_media = false
            if block.settings.collection.featured_image != blank
              assign collection_list_item_has_media = true
            elsif request.page_type == 'index'
              assign homepage_collection_products = block.settings.collection.products | sort: 'published_at' | reverse
              for homepage_collection_product in homepage_collection_products limit: 8
                assign homepage_collection_media = homepage_collection_product.featured_media.preview_image | default: homepage_collection_product.featured_image
                if homepage_collection_media != blank
                  assign collection_list_item_has_media = true
                  break
                endif
              endfor
            endif
          -%}
          <li
            id="Slide-{{ section.id }}-{{ animation_order }}"
            class="collection-list__item grid__item{% if show_mobile_slider %} slider__slide{% endif %}{% unless collection_list_item_has_media %} collection-list__item--no-media{% endunless %}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
            {{ block.shopify_attributes }}
            {% if settings.animations_reveal_on_scroll %}
              data-cascade
              style="--animation-order: {{ animation_order }};"
            {% endif %}
          >
            {% comment %}theme-check-disable UnusedAssign{% endcomment %}
            {%- assign placeholder_image_index = animation_order | minus: 1 | modulo: 4 | plus: 1 -%}
            {%- assign placeholder_image = 'collection-apparel-' | append: placeholder_image_index -%}
            {%- liquid
              assign collection_card_lazy_load = true
              if section.index == 1 and animation_order <= columns_mobile_int
                assign collection_card_lazy_load = false
              endif
            -%}
            {% render 'card-collection', card_collection: block.settings.collection, media_aspect_ratio: section.settings.image_ratio, columns: columns, placeholder_image: placeholder_image, lazy_load: collection_card_lazy_load, use_homepage_collection_image_strategy: request.page_type %}
            {% comment %}theme-check-enable UnusedAssign{% endcomment %}
          </li>
        {%- endfor -%}
      </ul>
      {%- if show_mobile_slider -%}
        <div class="slider-buttons collection-carousel__slider-buttons">
          <button
            type="button"
            class="slider-button slider-button--prev"
            name="previous"
            aria-label="{{ 'general.slider.previous_slide' | t }}"
          >
            {% render 'icon-caret' %}
          </button>
          <div
            class="slider-page-dots collection-carousel__page-dots"
            role="tablist"
            aria-label="{{ 'general.slider.name' | t }}"
          ></div>
          <button
            type="button"
            class="slider-button slider-button--next"
            name="next"
            aria-label="{{ 'general.slider.next_slide' | t }}"
          >
            {% render 'icon-caret' %}
          </button>
        </div>
      {%- endif -%}
    </slider-component>

    {%- if section.settings.show_view_all and visible_block_count < collections.size -%}
      <div
        class="center collection-list-view-all{% if show_mobile_slider %} small-hide medium-hide{% endif %}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
        {% if settings.animations_reveal_on_scroll %}
          data-cascade
        {% endif %}
      >
        <a
          href="{{ routes.collections_url }}"
          class="button"
          id="ViewAllButton-{{ section.id }}"
          aria-labelledby="ViewAllButton-{{ section.id }} SectionHeading-{{ section.id }}"
        >
          {{- 'sections.collection_list.view_all' | t -}}
        </a>
      </div>
    {%- endif -%}
  </div>
</div>
{%- endif -%}

{% schema %}
{
  "name": "t:sections.collection-list.name",
  "tag": "section",
  "class": "section section-collection-list",
  "max_blocks": 15,
  "disabled_on": {
    "groups": ["header", "footer"]
  },
  "settings": [
    {
      "type": "inline_richtext",
      "id": "title",
      "default": "Collections",
      "label": "t:sections.collection-list.settings.title.label"
    },
    {
      "type": "text",
      "id": "anchor_id",
      "label": "Section anchor ID",
      "info": "Optional. Adds an HTML id for in-page scrolling."
    },
    {
      "type": "select",
      "id": "heading_size",
      "options": [
        {
          "value": "h2",
          "label": "t:sections.all.heading_size.options__1.label"
        },
        {
          "value": "h1",
          "label": "t:sections.all.heading_size.options__2.label"
        },
        {
          "value": "h0",
          "label": "t:sections.all.heading_size.options__3.label"
        }
      ],
      "default": "h1",
      "label": "t:sections.all.heading_size.label"
    },
    {
      "type": "select",
      "id": "image_ratio",
      "options": [
        {
          "value": "adapt",
          "label": "t:sections.collection-list.settings.image_ratio.options__1.label"
        },
        {
          "value": "portrait",
          "label": "t:sections.collection-list.settings.image_ratio.options__2.label"
        },
        {
          "value": "square",
          "label": "t:sections.collection-list.settings.image_ratio.options__3.label"
        }
      ],
      "default": "square",
      "label": "t:sections.collection-list.settings.image_ratio.label",
      "info": "t:sections.collection-list.settings.image_ratio.info"
    },
    {
      "type": "range",
      "id": "columns_desktop",
      "min": 1,
      "max": 6,
      "step": 1,
      "default": 3,
      "label": "t:sections.collection-list.settings.columns_desktop.label"
    },
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "label": "t:sections.all.colors.label",
      "info": "t:sections.all.colors.has_cards_info",
      "default": "scheme-1"
    },
    {
      "type": "checkbox",
      "id": "show_view_all",
      "default": false,
      "label": "t:sections.collection-list.settings.show_view_all.label"
    },
    {
      "type": "header",
      "content": "t:sections.collection-list.settings.header_mobile.content"
    },
    {
      "type": "select",
      "id": "columns_mobile",
      "options": [
        {
          "value": "1",
          "label": "t:sections.collection-list.settings.columns_mobile.options__1.label"
        },
        {
          "value": "2",
          "label": "t:sections.collection-list.settings.columns_mobile.options__2.label"
        }
      ],
      "default": "1",
      "label": "t:sections.collection-list.settings.columns_mobile.label"
    },
    {
      "type": "checkbox",
      "id": "swipe_on_mobile",
      "default": false,
      "label": "t:sections.collection-list.settings.swipe_on_mobile.label"
    },
    {
      "type": "header",
      "content": "t:sections.all.padding.section_padding_heading"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_top",
      "default": 36
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_bottom",
      "default": 36
    }
  ],
  "blocks": [
    {
      "type": "featured_collection",
      "name": "t:sections.collection-list.blocks.featured_collection.name",
      "settings": [
        {
          "type": "collection",
          "id": "collection",
          "label": "t:sections.collection-list.blocks.featured_collection.settings.collection.label"
        }
      ]
    }
  ],
  "presets": [
    {
      "name": "t:sections.collection-list.presets.name",
      "blocks": [
        {
          "type": "featured_collection"
        },
        {
          "type": "featured_collection"
        },
        {
          "type": "featured_collection"
        }
      ]
    }
  ]
}
{% endschema %}
{% comment %}

This file has been rewritten to preserve the original behavior.

---
Changes:
- from: |-
    {% render 'card-collection',
                  card_collection: block.settings.collection,
                  media_aspect_ratio: section.settings.image_ratio,
                  columns: columns,
                  placeholder_image: placeholder_image,
                  lazy_load: collection_card_lazy_load,
                  use_homepage_collection_image_strategy: request.page_type == 'index'
                %}
  to: "{% render 'card-collection', card_collection: block.settings.collection, media_aspect_ratio:
    section.settings.image_ratio, columns: columns, placeholder_image: placeholder_image,
    lazy_load: collection_card_lazy_load, use_homepage_collection_image_strategy:
    request.page_type %}"
  position: 6523..6800
{% endcomment %}

{{ 'component-card.css' | asset_url | stylesheet_tag }}
{{ 'component-price.css' | asset_url | stylesheet_tag }}
{{ 'component-slider.css' | asset_url | stylesheet_tag }}
{{ 'template-collection.css' | asset_url | stylesheet_tag }}

{%- style -%}
  .section-{{ section.id }}-padding {
    padding-top: {{ section.settings.padding_top | times: 0.75 | round: 0 }}px;
    padding-bottom: {{ section.settings.padding_bottom | times: 0.75 | round: 0 }}px;
  }
  @media screen and (min-width: 750px) {
    .section-{{ section.id }}-padding {
      padding-top: {{ section.settings.padding_top }}px;
      padding-bottom: {{ section.settings.padding_bottom }}px;
    }
  }
{%- endstyle -%}

{%- liquid
  assign visible_collection_count = 0
  for block in section.blocks
    if block.settings.collection != blank and block.settings.collection.all_products_count > 0
      assign visible_collection_count = visible_collection_count | plus: 1
    endif
  endfor
-%}

{%- if visible_collection_count > 0 -%}
<div class="color-{{ section.settings.color_scheme }} isolate gradient">
  <div class="collection section-{{ section.id }}-padding" id="collection-{{ section.id }}" data-id="{{ section.id }}">
    <div class="collection__title title-wrapper title-wrapper--no-top-margin page-width{% if section.settings.swipe_on_mobile %} title-wrapper--self-padded-tablet-down{% endif %}">
      {%- if section.settings.title != blank -%}
        <h2 class="title inline-richtext {{ section.settings.heading_size }}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
          {{ section.settings.title }}
        </h2>
      {%- endif -%}
    </div>

    <slider-component class="slider-mobile-gutter{% if section.settings.swipe_on_mobile == false %} page-width{% endif %} page-width-desktop{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
      <ul id="Slider-{{ section.id }}" data-id="{{ section.id }}" class="grid product-grid contains-card contains-card--product{% if settings.card_style == 'standard' %} contains-card--standard{% endif %} grid--{{ section.settings.columns_desktop }}-col-desktop grid--{{ section.settings.columns_mobile }}-col-tablet-down{% if section.settings.swipe_on_mobile %} slider slider--tablet grid--peek{% endif %}" role="list" aria-label="{{ 'general.slider.name' | t }}">

        {%- assign render_count = 0 -%}
        {%- for block in section.blocks -%}
          {%- assign col = collections[block.settings.collection] -%}
          {%- if col == blank or col.products_count == 0 -%}
            {%- continue -%}
          {%- endif -%}

          {%- assign render_count = render_count | plus: 1 -%}
          {% comment %}theme-check-disable UnusedAssign{% endcomment %}
          {%- liquid
            assign collection_card_lazy_load = true
            if section.index == 1 and render_count <= 2
              assign collection_card_lazy_load = false
            endif
          -%}

          <li id="Slide-{{ section.id }}-{{ render_count }}" class="grid__item{% if section.settings.swipe_on_mobile %} slider__slide{% endif %}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}" {% if settings.animations_reveal_on_scroll %}data-cascade style="--animation-order: {{ render_count }};"{% endif %} {{ block.shopify_attributes }}>
            {% render 'card-collection', card_collection: col, media_aspect_ratio: section.settings.image_ratio, columns: section.settings.columns_desktop, lazy_load: collection_card_lazy_load, use_homepage_collection_image_strategy: request.page_type %}
            {% comment %}theme-check-enable UnusedAssign{% endcomment %}
          </li>
        {%- endfor -%}

      </ul>
      {%- if section.settings.swipe_on_mobile -%}
        <div class="slider-buttons collection-carousel__slider-buttons">
          <button type="button" class="slider-button slider-button--prev" name="previous" aria-label="{{ 'general.slider.previous_slide' | t }}" aria-controls="Slider-{{ section.id }}">
            {% render 'icon-caret' %}
          </button>
          <div class="slider-page-dots collection-carousel__page-dots" role="tablist" aria-label="{{ 'general.slider.name' | t }}"></div>
          <button type="button" class="slider-button slider-button--next" name="next" aria-label="{{ 'general.slider.next_slide' | t }}" aria-controls="Slider-{{ section.id }}">
            {% render 'icon-caret' %}
          </button>
        </div>
      {%- endif -%}
    </slider-component>

    {%- if section.settings.show_view_all -%}
      <div class="center collection__view-all{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
        <a href="{{ section.settings.view_all_link }}" class="{% if section.settings.view_all_style == 'link' %}link underlined-link{% elsif section.settings.view_all_style == 'solid' %}button{% else %}button button--secondary{% endif %}">
          {{ 'sections.featured_collection.view_all' | t }}
        </a>
      </div>
    {%- endif -%}
  </div>
</div>
{%- endif -%}

