                  use_homepage_collection_image_strategy: request.page_type == 'index'
                %}
  to: "{% render 'card-collection', card_collection: col, media_aspect_ratio: section.settings.image_ratio,
    columns: section.settings.columns_desktop, lazy_load: collection_card_lazy_load,
    use_homepage_collection_image_strategy: request.page_type %}"
